      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-remote-ssh-run\",\n  \"version\": \"0.1.1\",\n  \"description\": \"DeepSeek Harness plugin: allowlisted SSH to Unix/AIX/macOS hosts (read-only by default).\",\n  \"license\": \"MIT\",\n  \"repository\": { \"type\": \"git\", \"url\": \"https://github.com/173787247/dsh-remote-ssh.git\" },\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"engines\": { \"node\": \">=18\" },\n  \"scripts\": { \"test\": \"node --test test/*.test.js\" },\n  \"files\": [\"index.js\", \"lib\", \"cordis.patch.yml\", \"README.md\", \"README.en.md\", \"README.zh.md\", \"LICENSE\", \"CHANGELOG.md\", \"examples\", \"docs\"],\n  \"keywords\": [\"dsh-plugin\", \"deepseek-harness\", \"ssh\", \"aix\", \"unix\", \"macos\"],\n  \"dsh\": { \"bundle\": { \"patch\": \"./cordis.patch.yml\" } }\n}\n"
